window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d8c67b94514290a6"]={"versions": [{"id": "FIG-d8c67b94514290a6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Mappings von zusammengesetzten Datentypen (Composite Data Types) auf System-Signal-Gruppen im Kontext der AUTOSAR-Systembeschreibung (System Template, Daten-Mapping).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>DataMapping</code></strong> (abstrakt): Basisklasse mit Attribut <code>communicationDirection :CommunicationDirectionType [0..1]</code>.\n</li><li><strong><code>SenderReceiverToSignalGroupMapping</code></strong>: Spezialisierung von <code>DataMapping</code>.\n<ul class=\"fig-list\"><li>Assoziiert via <code>«instanceRef» +dataElement</code> einen <code>VariableDataPrototype</code> (Generalisierung: <code>AutosarDataPrototype</code>).\n</li><li>Referenziert via <code>+signalGroup 1</code> ein <code>SystemSignalGroup</code> (<code>ARElement</code>).\n</li><li>Komponiert via <code>+typeMapping 1</code> genau ein <code>SenderRecCompositeTypeMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecCompositeTypeMapping</code></strong> (abstrakt): Basisklasse für zusammengesetzte Mappings.\n<ul class=\"fig-list\"><li>Ermöglicht hierarchische Schachtelung über rekursive Assoziationen <code>+complexTypeMapping 0..1</code> ausgehend von <code>SenderRecRecordElementMapping</code> bzw. <code>SenderRecArrayElementMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecRecordTypeMapping</code></strong>: Spezialisierung von <code>SenderRecCompositeTypeMapping</code>.\n<ul class=\"fig-list\"><li>Komponiert über <code>+recordElementMapping *</code> Instanzen von <code>SenderRecRecordElementMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecRecordElementMapping</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert optional <code>+applicationRecordElement 0..1</code> (<code>ApplicationRecordElement</code>, Subklasse von <code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Referenziert optional <code>+implementationRecordElement 0..1</code> (<code>ImplementationDataTypeElement</code>, Subklasse von <code>Identifiable</code>).\n</li><li>Referenziert optional <code>+systemSignal 0..1</code> (<code>SystemSignal</code>, Subklasse von <code>ARElement</code>).\n</li><li>Besitzt Assoziation <code>+complexTypeMapping 0..1</code> zu <code>SenderRecCompositeTypeMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecArrayTypeMapping</code></strong>: Spezialisierung von <code>SenderRecCompositeTypeMapping</code>.\n<ul class=\"fig-list\"><li>Komponiert über <code>+arrayElementMapping *</code> Instanzen von <code>SenderRecArrayElementMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecArrayElementMapping</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert via <code>+indexedArrayElement 1</code> eine Instanz von <code>IndexedArrayElement</code>.\n</li><li>Referenziert optional <code>+systemSignal 0..1</code> (<code>SystemSignal</code>).\n</li><li>Besitzt Assoziation <code>+complexTypeMapping 0..1</code> zu <code>SenderRecCompositeTypeMapping</code>.\n</li></ul>\n</li><li><strong><code>IndexedArrayElement</code></strong>:\n<ul class=\"fig-list\"><li>Attribut: <code>index :Integer</code>.\n</li><li>Referenziert optional <code>+applicationArrayElement 0..1</code> (<code>ApplicationArrayElement</code>, Subklasse von <code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Referenziert optional <code>+implementationArrayElement 0..1</code> (<code>ImplementationDataTypeElement</code>).\n</li></ul>\n</li><li><strong><code>ApplicationArrayElement</code></strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>arraySizeSemantics :ArraySizeSemanticsEnum [0..1]</code>, <code>«atpVariation» maxNumberOfElements :PositiveInteger</code>.\n</li></ul>\n</li><li><strong><code>SystemSignal</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>dynamicLength :Boolean</code>.\n</li></ul>\n</li><li><strong><code>SystemSignalGroup</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Assoziiert über <code>+systemSignal *</code> mehrere <code>SystemSignal</code>-Elemente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzablaufspezifikation. Das Diagramm modelliert deklarative Abbildungsregeln zwischen Software-Datenstrukturen (Application- und Implementation-Ebene) und Übertragungsstrukturen der Kommunikationsmatrix (System Signals und Signal Groups). Rekursive Schachtelungen über <code>+complexTypeMapping</code> ermöglichen die vollständige Baumtraversierung komplexer Datentypen bis zu elementaren Signalen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Modellierung und Generierung von Signal-Group-Mappings für Sender-Receiver-Kommunikation bei Composite-Typen (Records und Arrays):</p>\n<ul class=\"fig-list\"><li>Mappings können wahlweise auf Application-Datentypebene (<code>ApplicationRecordElement</code>, <code>ApplicationArrayElement</code>) oder Implementation-Datentypebene (<code>ImplementationDataTypeElement</code>) referenziert werden.\n</li><li>Elementare Blätter der Datenstruktur werden über <code>+systemSignal [0..1]</code> einzelnen Signalen innerhalb der Signal-Gruppe (<code>SystemSignalGroup</code>) zugeordnet.\n</li><li>Dynamische Array- und Signal-Eigenschaften werden durch <code>arraySizeSemantics</code>, <code>maxNumberOfElements</code> sowie <code>dynamicLength</code> formal parametrisiert.\n</li></ul>"}, {"id": "FIG-dc0c22a4f9802bad", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Mappings von zusammengesetzten Datentypen (Composite Data Types) auf System-Signal-Gruppen im Kontext der AUTOSAR-Systembeschreibung (System Template, Daten-Mapping).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>DataMapping</code></strong> (abstrakt): Basisklasse mit Attribut <code>communicationDirection :CommunicationDirectionType [0..1]</code>.\n</li><li><strong><code>SenderReceiverToSignalGroupMapping</code></strong>: Spezialisierung von <code>DataMapping</code>.\n<ul class=\"fig-list\"><li>Assoziiert via <code>«instanceRef» +dataElement</code> einen <code>VariableDataPrototype</code> (Generalisierung: <code>AutosarDataPrototype</code>).\n</li><li>Referenziert via <code>+signalGroup 1</code> ein <code>SystemSignalGroup</code> (<code>ARElement</code>).\n</li><li>Komponiert via <code>+typeMapping 1</code> genau ein <code>SenderRecCompositeTypeMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecCompositeTypeMapping</code></strong> (abstrakt): Basisklasse für zusammengesetzte Mappings.\n<ul class=\"fig-list\"><li>Ermöglicht hierarchische Schachtelung über rekursive Assoziationen <code>+complexTypeMapping 0..1</code> ausgehend von <code>SenderRecRecordElementMapping</code> bzw. <code>SenderRecArrayElementMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecRecordTypeMapping</code></strong>: Spezialisierung von <code>SenderRecCompositeTypeMapping</code>.\n<ul class=\"fig-list\"><li>Komponiert über <code>+recordElementMapping *</code> Instanzen von <code>SenderRecRecordElementMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecRecordElementMapping</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert optional <code>+applicationRecordElement 0..1</code> (<code>ApplicationRecordElement</code>, Subklasse von <code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Referenziert optional <code>+implementationRecordElement 0..1</code> (<code>ImplementationDataTypeElement</code>, Subklasse von <code>Identifiable</code>).\n</li><li>Referenziert optional <code>+systemSignal 0..1</code> (<code>SystemSignal</code>, Subklasse von <code>ARElement</code>).\n</li><li>Besitzt Assoziation <code>+complexTypeMapping 0..1</code> zu <code>SenderRecCompositeTypeMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecArrayTypeMapping</code></strong>: Spezialisierung von <code>SenderRecCompositeTypeMapping</code>.\n<ul class=\"fig-list\"><li>Komponiert über <code>+arrayElementMapping *</code> Instanzen von <code>SenderRecArrayElementMapping</code>.\n</li></ul>\n</li><li><strong><code>SenderRecArrayElementMapping</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert via <code>+indexedArrayElement 1</code> eine Instanz von <code>IndexedArrayElement</code>.\n</li><li>Referenziert optional <code>+systemSignal 0..1</code> (<code>SystemSignal</code>).\n</li><li>Besitzt Assoziation <code>+complexTypeMapping 0..1</code> zu <code>SenderRecCompositeTypeMapping</code>.\n</li></ul>\n</li><li><strong><code>IndexedArrayElement</code></strong>:\n<ul class=\"fig-list\"><li>Attribut: <code>index :Integer</code>.\n</li><li>Referenziert optional <code>+applicationArrayElement 0..1</code> (<code>ApplicationArrayElement</code>, Subklasse von <code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Referenziert optional <code>+implementationArrayElement 0..1</code> (<code>ImplementationDataTypeElement</code>).\n</li></ul>\n</li><li><strong><code>ApplicationArrayElement</code></strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>arraySizeHandling :ArraySizeHandlingEnum [0..1]</code>, <code>arraySizeSemantics :ArraySizeSemanticsEnum [0..1]</code>, <code>«atpVariation» maxNumberOfElements :PositiveInteger</code>.\n</li></ul>\n</li><li><strong><code>SystemSignal</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>dynamicLength :Boolean</code>.\n</li></ul>\n</li><li><strong><code>SystemSignalGroup</code></strong> (<code>ARElement</code>):\n<ul class=\"fig-list\"><li>Assoziiert über <code>+systemSignal *</code> mehrere <code>SystemSignal</code>-Elemente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzablaufspezifikation. Das Diagramm modelliert deklarative Abbildungsregeln zwischen Software-Datenstrukturen (Application- und Implementation-Ebene) und Übertragungsstrukturen der Kommunikationsmatrix (System Signals und Signal Groups). Rekursive Schachtelungen über <code>+complexTypeMapping</code> ermöglichen die vollständige Baumtraversierung komplexer Datentypen bis zu elementaren Signalen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Modellierung und Generierung von Signal-Group-Mappings für Sender-Receiver-Kommunikation bei Composite-Typen (Records und Arrays):</p>\n<ul class=\"fig-list\"><li>Mappings können wahlweise auf Application-Datentypebene (<code>ApplicationRecordElement</code>, <code>ApplicationArrayElement</code>) oder Implementation-Datentypebene (<code>ImplementationDataTypeElement</code>) referenziert werden.\n</li><li>Elementare Blätter der Datenstruktur werden über <code>+systemSignal [0..1]</code> einzelnen Signalen innerhalb der Signal-Gruppe (<code>SystemSignalGroup</code>) zugeordnet.\n</li><li>Dynamische Array- und Signal-Eigenschaften werden durch <code>arraySizeHandling</code>, <code>arraySizeSemantics</code>, <code>maxNumberOfElements</code> sowie <code>dynamicLength</code> formal parametrisiert.\n</li></ul>"}], "trans": [{"from": "FIG-d8c67b94514290a6", "to": "FIG-dc0c22a4f9802bad", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>arraySizeHandling :ArraySizeHandlingEnum [0..1]</code> in Klasse <code>ApplicationArrayElement</code> ergänzt.\n</li></ul>"}]};
